"""Stack-based configuration manager that merges settings from multiple sources."""

from __future__ import annotations

import json
import os
import sys
from pathlib import Path
from typing import Any, Dict, List, Optional, Union


class SegmentTree:
    """A stack-based configuration manager that parses and merges configs from multiple sources.

    Supports push/pop/peek/is_empty operations for managing configuration layers.
    Each layer can come from files (JSON, YAML, .env), environment variables, or CLI arguments.
    Later layers override earlier ones when values conflict.

    Example:
        >>> tree = SegmentTree()
        >>> tree.push({"app": {"name": "myapp", "debug": False}})
        >>> tree.push("config.json")
        >>> tree.push("--debug=true --port=8080", source_type="cli")
        >>> config = tree.peek()
        >>> config["app"]["debug"]
        True
    """

    def __init__(self) -> None:
        """Initialize an empty configuration stack."""
        self._stack: List[Dict[str, Any]] = []

    def push(self, source: Union[str, Path, Dict[str, Any], List[str]], source_type: str = "auto") -> None:
        """Push a new configuration source onto the stack.

        Args:
            source: Configuration source - file path, dict, env var string, or CLI args list.
            source_type: Type hint for parsing. One of "file", "env", "cli", "dict", or "auto".
                         "auto" detects based on source format.

        Raises:
            ValueError: If source type is unsupported or cannot be parsed.
            FileNotFoundError: If source is a file path that doesn't exist.
        """
        config = self._parse_source(source, source_type)
        self._stack.append(config)

    def pop(self) -> Optional[Dict[str, Any]]:
        """Remove and return the top configuration layer.

        Returns:
            The popped configuration dict, or None if the stack is empty.
        """
        if self.is_empty():
            return None
        return self._stack.pop()

    def peek(self) -> Optional[Dict[str, Any]]:
        """Return the current merged configuration without modifying the stack.

        Merges all layers with later layers taking precedence.

        Returns:
            Merged configuration dict, or None if the stack is empty.
        """
        if self.is_empty():
            return None
        return self._merge_all()

    def is_empty(self) -> bool:
        """Check if the configuration stack is empty.

        Returns:
            True if no configuration sources have been pushed.
        """
        return len(self._stack) == 0

    def __len__(self) -> int:
        """Return the number of configuration layers in the stack."""
        return len(self._stack)

    def __repr__(self) -> str:
        return f"SegmentTree(layers={len(self._stack)})"

    # ------------------------------------------------------------------
    # Source parsing
    # ------------------------------------------------------------------

    def _parse_source(self, source: Union[str, Path, Dict[str, Any], List[str]], source_type: str) -> Dict[str, Any]:
        """Parse a configuration source into a dictionary."""
        if isinstance(source, dict):
            return source

        if isinstance(source, list):
            return self._parse_cli_args(source)

        source_str = str(source)

        if source_type == "auto":
            source_type = self._detect_source_type(source_str)

        if source_type == "env":
            return self._parse_env_string(source_str)
        if source_type == "cli":
            return self._parse_cli_args(source_str.split())
        if source_type == "file":
            return self._parse_file(source_str)

        raise ValueError(f"Cannot auto-detect source type for: {source_str!r}")

    def _detect_source_type(self, source: str) -> str:
        """Auto-detect the type of a string source."""
        if source.startswith("--") or source.startswith("-"):
            return "cli"
        if "=" in source and "\n" not in source and Path(source).suffix == "":
            return "env"
        path = Path(source)
        if path.exists() and path.is_file():
            return "file"
        return "cli"

    def _parse_file(self, path: str) -> Dict[str, Any]:
        """Parse a configuration file (JSON, YAML, or .env)."""
        p = Path(path)
        if not p.exists():
            raise FileNotFoundError(f"Config file not found: {path}")

        ext = p.suffix.lower()
        if ext == ".json":
            return self._parse_json(p)
        if ext in (".yaml", ".yml"):
            return self._parse_yaml(p)
        if ext == ".env":
            return self._parse_env_file(p)

        # Try JSON first, fall back to .env
        try:
            return self._parse_json(p)
        except (json.JSONDecodeError, ValueError):
            return self._parse_env_file(p)

    @staticmethod
    def _parse_json(path: Path) -> Dict[str, Any]:
        """Parse a JSON file."""
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            raise ValueError(f"JSON root must be an object, got {type(data).__name__}")
        return data

    @staticmethod
    def _parse_yaml(path: Path) -> Dict[str, Any]:
        """Parse a YAML file."""
        try:
            import yaml
        except ImportError:
            raise ImportError("PyYAML is required for YAML support: pip install pyyaml")
        with open(path, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
        return data if isinstance(data, dict) else {}

    @staticmethod
    def _parse_env_file(path: Path) -> Dict[str, Any]:
        """Parse a .env file into a flat dictionary."""
        config: Dict[str, Any] = {}
        with open(path, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    continue
                key, _, value = line.partition("=")
                key = key.strip()
                value = value.strip().strip("\"'")
                config[key] = SegmentTree._cast_value(value)
        return config

    @staticmethod
    def _parse_env_string(env_str: str) -> Dict[str, Any]:
        """Parse a KEY=VALUE environment variable string."""
        config: Dict[str, Any] = {}
        for pair in env_str.split(";"):
            pair = pair.strip()
            if "=" in pair:
                key, _, value = pair.partition("=")
                config[key.strip()] = SegmentTree._cast_value(value.strip())
        return config

    @staticmethod
    def _parse_cli_args(args: List[str]) -> Dict[str, Any]:
        """Parse CLI arguments into a dictionary.

        Supports ``--key=value``, ``--key value``, and ``--flag`` (set to True).
        Single-letter flags ``-k value`` are also supported.
        """
        config: Dict[str, Any] = {}
        i = 0
        while i < len(args):
            arg = args[i]
            if arg.startswith("--"):
                arg = arg[2:]
                if "=" in arg:
                    key, _, value = arg.partition("=")
                    config[key] = SegmentTree._cast_value(value)
                elif i + 1 < len(args) and not args[i + 1].startswith("-"):
                    config[arg] = SegmentTree._cast_value(args[i + 1])
                    i += 1
                else:
                    config[arg] = True
            elif arg.startswith("-") and len(arg) == 2:
                key = arg[1]
                if i + 1 < len(args) and not args[i + 1].startswith("-"):
                    config[key] = SegmentTree._cast_value(args[i + 1])
                    i += 1
                else:
                    config[key] = True
            i += 1
        return config

    @staticmethod
    def _cast_value(value: str) -> Any:
        """Cast a string value to the most appropriate Python type."""
        lower = value.lower()
        if lower in ("true", "yes", "on"):
            return True
        if lower in ("false", "no", "off"):
            return False
        if lower == "null" or lower == "none":
            return None
        try:
            return int(value)
        except ValueError:
            pass
        try:
            return float(value)
        except ValueError:
            pass
        return value

    # ------------------------------------------------------------------
    # Merging
    # ------------------------------------------------------------------

    def _merge_all(self) -> Dict[str, Any]:
        """Merge all layers; later layers override earlier ones."""
        merged: Dict[str, Any] = {}
        for layer in self._stack:
            self._deep_merge(merged, layer)
        return merged

    @staticmethod
    def _deep_merge(base: Dict[str, Any], override: Dict[str, Any]) -> None:
        """Recursively merge *override* into *base* in-place."""
        for key, value in override.items():
            if key in base and isinstance(base[key], dict) and isinstance(value, dict):
                SegmentTree._deep_merge(base[key], value)
            else:
                base[key] = value


# ------------------------------------------------------------------
# Quick self-test
# ------------------------------------------------------------------

if __name__ == "__main__":
    tree = SegmentTree()
    assert tree.is_empty()
    assert tree.peek() is None
    assert tree.pop() is None

    # Push a dict layer
    tree.push({"app": {"name": "myapp", "debug": False, "port": 3000}})
    assert not tree.is_empty()
    assert len(tree) == 1

    # Push CLI args
    tree.push("--debug=true --port=8080 --verbose", source_type="cli")
    assert len(tree) == 2

    config = tree.peek()
    assert config["app"]["debug"] is False  # dict layer, not overridden by flat key
    assert config["debug"] is True           # CLI flat key
    assert config["port"] == 8080            # CLI overrides flat key
    assert config["verbose"] is True

    # Pop removes top layer
    popped = tree.pop()
    assert popped == {"debug": True, "port": 8080, "verbose": True}
    assert len(tree) == 1

    # Push env string
    tree.push("DATABASE_URL=postgres://localhost/db;POOL_SIZE=10", source_type="env")
    config = tree.peek()
    assert config["DATABASE_URL"] == "postgres://localhost/db"
    assert config["POOL_SIZE"] == 10
    assert config["app"]["name"] == "myapp"

    # Push .env file
    env_file = Path("/tmp/test_config.env")
    env_file.write_text("APP_NAME=overridden\nSECRET_KEY=abc123\n")
    tree.push(str(env_file))
    config = tree.peek()
    assert config["APP_NAME"] == "overridden"
    assert config["SECRET_KEY"] == "abc123"
    assert config["app"]["name"] == "myapp"  # deep nested key preserved
    env_file.unlink()

    # Push JSON file
    json_file = Path("/tmp/test_config.json")
    json_file.write_text('{"app": {"version": "2.0"}, "features": ["auth", "logging"]}')
    tree.push(str(json_file))
    config = tree.peek()
    assert config["app"]["version"] == "2.0"
    assert config["app"]["name"] == "myapp"  # deep merge preserved
    assert config["features"] == ["auth", "logging"]
    json_file.unlink()

    # repr
    assert "layers=4" in repr(tree)

    print("All tests passed.")
